def planta_pid(Kp=10.0, Ti=0.1, Td=0.0, T_amostragem=0.5, N_amostras=150, plot=True):

    sistema_discreto = planta.sample(T_amostragem, method="zoh")

    NumD = sistema_discreto.num[0][0]
    DenD = sistema_discreto.den[0][0]

    yr = np.zeros(N_amostras)
    y_med = np.zeros(N_amostras)

    yr[0:50] = 1.0
    yr[50:100] = 2.0
    yr[100:150] = 0.75

    y = np.zeros(N_amostras)
    u = np.zeros(N_amostras)

    erro = np.zeros(N_amostras)
    s_int = np.zeros(N_amostras)

    kp = Kp
    ki = Kp * T_amostragem / Ti if Ti > 1e-3 else 0
    kd = Kp * Td / T_amostragem

    for k in range(2, N_amostras):
        y[k] = (
            -DenD[1] * y[k - 1]
            - DenD[2] * y[k - 2]
            + NumD[0] * u[k - 1]
            + NumD[1] * u[k - 2]
        )

        # se quiser desconsiderar o ruido coloque 0.00
        ruido = np.random.normal(0, 0.0)
        y_med[k] = y[k] + ruido

        # erro usando medição
        erro[k] = yr[k] - y_med[k]

        s_int[k] = s_int[k - 1] + erro[k]

        u[k] = kp * erro[k] + ki * s_int[k] + kd * (erro[k] - erro[k - 1])

    tempo = np.arange(0, N_amostras) * T_amostragem

    ise = np.sum(erro**2) * T_amostragem
    iae = np.sum(np.abs(erro)) * T_amostragem
    itae = np.sum(tempo * np.abs(erro)) * T_amostragem

    y_segment = y_med[:50]
    ref = 1.0

    overshoot = (
        (np.max(y_segment) - ref) / ref * 100
        if np.max(y_segment) > ref
        else 0
    )

    erro_final = abs(ref - y_segment[-1])

    sup = ref * 1.02
    inf = ref * 0.98

    indices_fora = np.where((y_segment < inf) | (y_segment > sup))[0]

    if len(indices_fora):
        tempo_acomod = tempo[indices_fora[-1] + 1]
    else:
        tempo_acomod = tempo[0]
#apenas plot do resultado final em caso de otimização
    if plot:
        fig, ax = plt.subplots(figsize=(9, 4))

        ax.plot(tempo, y, label="Variavel Controlada")
        ax.plot(tempo, yr, "--", label="Setpoint")

        ax.set_title(f"PID | Kp={Kp} Ti={Ti} Td={Td}")
        ax.set_xlabel("Tempo (s)")
        ax.set_ylabel("Amplitude")

        ax.grid(True)
        ax.legend()

        plt.show()

        buf = io.BytesIO()
        plt.savefig(buf, format="png")
        buf.seek(0)

        img64 = base64.b64encode(buf.getvalue()).decode("utf-8")

        plt.close()

    else:
        img64 = None

    return {
        "Kp": Kp,
        "Ti": Ti,
        "Td": Td,
        "overshoot": round(overshoot, 2),
        "tempo_acomod": round(tempo_acomod, 2),
        "erro_final": round(erro_final, 4),
        "ise": round(ise, 2),
        "iae": round(iae, 2),
        "itae": round(itae, 2),
        "grafico": img64,
    }

