class AgentState(TypedDict, total=False):
    pergunta: str
    classificacao: str
    parametros: dict
    resultado: dict
    resposta_tecnica: str
    resposta: str
    citacoes: list

def node_triagem(state: AgentState) -> AgentState:
    print("\n🔎 Executando nó de triagem...")

    saida = triagem(state["pergunta"])

    classificacao = saida["decisao"].upper().strip()

    print("Classificação:", classificacao)

    parametros = {
        "kp": saida.get("kp"),
        "ti": saida.get("ti"),
        "td": saida.get("td"),
        "ganho_alvo": saida.get("ganho_alvo"),
        "erro_alvo": saida.get("erro_alvo")
    }

    return {
        **state,
        "classificacao": classificacao,
        "parametros": parametros
    }

def node_teoria(state: AgentState):

    print("\n📚 Executando nó de teoria (RAG)...")

    pergunta = state["pergunta"]

    rag_resp = perguntar_controle_RAG(pergunta)

    print("RAG encontrou contexto:", rag_resp["contexto_encontrado"])

    if rag_resp["contexto_encontrado"]:
        resposta_final = rag_resp["answer"]
        citacoes = rag_resp["citacoes"]

    else:
        prompt = f"""
Você é um especialista em sistemas de controle em malha fechada.

Explique a pergunta abaixo de forma clara para um estudante de engenharia elétrica.

Pergunta:
{pergunta}

Observação:
Não foram encontrados documentos na base de conhecimento.
Responda com base apenas no conhecimento geral de engenharia de controle.
"""
        resposta_llm = llm.invoke(prompt)
        resposta_final = resposta_llm.content
        citacoes = []

    return {
        **state,
        "resposta": resposta_final,
        "citacoes": citacoes
    }

def node_simular(state: AgentState):

    print("\n⚙️ Executando simulação PID...")

    p = state["parametros"]

    kp = p.get("kp")
    ti = p.get("ti")
    td = p.get("td")

    if kp is None:
        kp = 10.0
    if ti is None:
        ti = 0.1
    if td is None:
        td = 0.0

   #limites de ganhos
    kp_original = kp

    kp = max(0.0, min(kp, 50.0))
    ti = max(0.01, min(ti, 5.0))
    td = max(0.0, min(td, 2.0))

    if kp != kp_original:
        print(f"⚠️ Kp ajustado de {kp_original} para {kp}")

    print(f"Parâmetros iniciais: Kp={kp}, Ti={ti}, Td={td}")

#controle de overshoot
    max_tentativas = 5
    fator_reducao = 0.7

    melhor = None

    for tentativa in range(max_tentativas):

        try:
           # apenas plot o grafico no final
            resultado = planta_pid(Kp=kp, Ti=ti, Td=td, plot=False)

            overshoot = resultado["overshoot"]

            if np.isnan(overshoot) or np.isinf(overshoot):
                raise ValueError("Overshoot inválido")

            print(f"Tentativa {tentativa+1}: Overshoot = {overshoot:.2f}%")

            melhor = resultado

            if overshoot <= 30:
                print("✅ Overshoot dentro do limite")
                break

            print("⚠️ Overshoot alto, reduzindo ganho...")

            kp *= fator_reducao
            td *= fator_reducao

        except Exception as e:
            print("⚠️ Erro na simulação:", str(e))

            kp *= fator_reducao
            td *= fator_reducao

    if melhor is not None:

        print("\n📊 Gerando simulação final com gráfico...")

        resultado_final = planta_pid(
            Kp=melhor["Kp"],
            Ti=melhor["Ti"],
            Td=melhor["Td"],
            plot=True
        )

    else:
        print("❌ Não foi possível simular a planta")

        resultado_final = {
            "Kp": kp,
            "Ti": ti,
            "Td": td,
            "overshoot": None,
            "tempo_acomod": None,
            "erro_final": None,
            "ise": None,
            "iae": None,
            "itae": None,
            "grafico": None,
            "erro": "Falha na simulação"
        }

    return {
        **state,
        "resultado": resultado_final
    }

def node_resposta_final(state: AgentState):

    print("\n📊 Gerando resposta técnica...")

    r = state["resultado"]

    texto = f"""
Simulação PID realizada.

Parâmetros do controlador:

Kp = {r["Kp"]}
Ti = {r["Ti"]}
Td = {r["Td"]}

Métricas:

Overshoot: {r["overshoot"]} %
Tempo de acomodação: {r["tempo_acomod"]} s
Erro final: {r["erro_final"]}

ISE: {r["ise"]}
IAE: {r["iae"]}
ITAE: {r["itae"]}

"""

    return {
        **state,
        "resposta_tecnica": texto
    }

def node_otimizar(state: AgentState):

    print("\n🧠 Executando otimização...")

    melhor = None
    melhor_custo = 1e9

    for kp in np.linspace(1, 30, 10):
        for ti in np.linspace(0.05, 1, 10):
            for td in np.linspace(0, 0.5, 6):

                try:
                    r = planta_pid(kp, ti, td, plot=False)

                    custo = r["ise"]

                    if np.isnan(custo) or np.isinf(custo):
                        continue

                    if custo < melhor_custo:
                        melhor_custo = custo
                        melhor = r

                except:
                    continue

    if melhor is not None:

        print("\n✅ Melhor solução encontrada")

        melhor_final = planta_pid(
            melhor["Kp"],
            melhor["Ti"],
            melhor["Td"],
            plot=True
        )

        return {
            **state,
            "resultado": melhor_final
        }

    else:
        print("❌ Nenhuma solução válida encontrada")

        return {
            **state,
            "resultado": None
        }

def node_llm(state: AgentState):

    print("\n🤖 Refinando resposta com LLM...")

    texto = state.get("resposta_tecnica", state.get("resposta", ""))

    prompt = f"""
Você é um especialista em sistemas de controle.

Explique o conteúdo abaixo de forma clara e didática:

{texto}
"""

    resposta = llm.invoke(prompt)

    return {
        **state,
        "resposta": resposta.content
    }

workflow = StateGraph(AgentState)

workflow.add_node("triagem", node_triagem)
workflow.add_node("simular", node_simular)
workflow.add_node("teoria", node_teoria)
workflow.add_node("otimizar", node_otimizar)
workflow.add_node("resposta_final", node_resposta_final)
workflow.add_node("llm", node_llm)

# entrada
workflow.add_edge(START, "triagem")

# decisão
workflow.add_conditional_edges(
    "triagem",
    lambda x: x["classificacao"],
    {
        "SIMULAR": "simular",
        "TEORIA": "teoria",
        "OTIMIZAR": "otimizar"
    }
)

# fluxos
workflow.add_edge("simular", "resposta_final")
workflow.add_edge("otimizar", "resposta_final")

workflow.add_edge("resposta_final", "llm")
workflow.add_edge("teoria", "llm")

workflow.add_edge("llm", END)

# compilar
app = workflow.compile()

