import gradio as gr
import base64
import io
from PIL import Image

#Função principal
def executar_sistema(pergunta):

    resultado = app.invoke(
        {"pergunta": pergunta},
        config={"recursion_limit": 10}
    )

    resposta = resultado.get("resposta", "Sem resposta")

    grafico = None

    if "resultado" in resultado and resultado["resultado"]:
        img64 = resultado["resultado"].get("grafico")

        if img64:
            img_bytes = base64.b64decode(img64)
            grafico = Image.open(io.BytesIO(img_bytes))

    return resposta, grafico


#print do fluxograma
